/** Base URL of a provider connection: the operator's override (flag or NEXUS_<ID>_BASE_URL), else the provider default. */
export function providerBaseUrl(id: string, flag?: string): string {
  const url = flag?.trim() || operatorSetting(baseUrlSetting(id)) || providerDefinition(id)?.baseUrl;
  if (!url || !originOf(url)) {
    throw new Error(`Provider '${id}' needs a base URL: pass --base-url or set ${baseUrlSetting(id)} in ~/.config/nexus/config.env.`);
  }
  const parsed = new URL(url.trim());
  if (parsed.username || parsed.password) throw new Error(`Provider '${id}' base URL must not contain credentials; the key is sent as a header.`);
  return url.trim().replace(/\/+$/, "");
}

/**

/** A configured reasoning effort the selected model does not list (models.dev data); silent when the model has no data. */
const reasoningEffortCheck: Check = async (ctx) => {
  const { config } = ctx;
  if (!config?.reasoningEffort) return f("config.reasoning_effort", "config", "skip", "No reasoning effort is configured.");
  const levels = config.provider && config.model ? effortLevels(config.provider, config.model) : undefined;
  if (!levels) return f("config.reasoning_effort", "config", "skip", "The model's reasoning effort levels are not known, so the setting was not checked.", [`effort ${config.reasoningEffort}`]);
  if (!levels.includes(config.reasoningEffort)) {
    return f("config.reasoning_effort", "config", "warn", `${config.model} does not list reasoning effort "${config.reasoningEffort}".`, [`listed: ${levels.join(", ")}`], `Set NEXUS_REASONING_EFFORT to one of: ${levels.join(", ")}.`);
  }
  return f("config.reasoning_effort", "config", "pass", `Reasoning effort "${config.reasoningEffort}" is one the model lists.`, [`listed: ${levels.join(", ")}`]);
};

/** Providers the operator declared in ~/.config/nexus/providers.json: each needs a credential. An unreadable file is reported by config.valid. */
const providersFileCheck: Check = async () => {
  const own = allProviders().filter((d) => providerSource(d.id) === "providers.json");
  if (!own.length) return f("config.providers_file", "config", "skip", "No operator providers are declared (~/.config/nexus/providers.json).");
  const missing = own.filter((d) => d.auth !== "none" && !resolveCredential(d.id, d.credentialEnv));
  const evidence = own.map((d) => `${d.id}: ${d.protocol} ${d.baseUrl ?? ""} ${missing.includes(d) ? "(no credential)" : "(credential found)"}`);
  if (missing.length) {
    return f("config.providers_file", "config", "warn", `${missing.length} operator-declared provider(s) have no credential.`, evidence, `Set ${missing.map((d) => (d.credentialEnv ? `$${d.credentialEnv}` : d.id)).join(", ")} or run \`nexus connect <provider>\`.`);
  }
  return f("config.providers_file", "config", "pass", `${own.length} operator-declared provider(s) are valid and have credentials.`, evidence);
};

